import React, { useEffect, useState } from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import api from "../utils/api";

const AccountDetails = () => {
  const { accountId } = useParams();
  const navigate = useNavigate();

  const [account, setAccount] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  // Get logged-in user information
  const getLoggedInUser = () => {
    try {
      const user = localStorage.getItem("currentUser");

      if (user) {
        return JSON.parse(user);
      }

      // If your login stores role separately
      return {
        role: localStorage.getItem("role"),
        accountId: localStorage.getItem("accountId"),
        userId: localStorage.getItem("userId"),
      };
    } catch (err) {
      return {
        role: localStorage.getItem("role"),
        accountId: localStorage.getItem("accountId"),
        userId: localStorage.getItem("userId"),
      };
    }
  };

  const currentUser = getLoggedInUser();

  const role = String(currentUser?.role || "").toUpperCase();

  /*
   * USER can perform transactions only on their own account.
   *
   * This assumes your login stores the user's accountId in:
   * localStorage.currentUser.accountId
   * OR
   * localStorage.accountId
   */
  const isOwner =
    role === "USER" &&
    String(currentUser?.accountId || "") === String(accountId);

  const isAdmin = role === "ADMIN";

  // Only the account owner can perform transactions
  const canTransact = isOwner;

  useEffect(() => {
    const loadAccountDetails = async () => {
      try {
        setLoading(true);
        setError("");

        // Fetch account details
        const accountResponse = await api.fetchAccount(accountId);

        setAccount(accountResponse.data);

        // Fetch transaction history
        try {
          const transactionResponse =
            await api.fetchTransactionHistory(accountId);

          setTransactions(transactionResponse.data || []);
        } catch (transactionError) {
          console.error(
            "Transaction history error:",
            transactionError
          );

          setTransactions([]);
        }
      } catch (err) {
        console.error("Account details error:", err);

        setError(
          err?.response?.data?.message ||
            err?.response?.data ||
            "Unable to load account details."
        );
      } finally {
        setLoading(false);
      }
    };

    loadAccountDetails();
  }, [accountId]);

  const formatDate = (date) => {
    if (!date) return "-";

    try {
      return new Date(date).toLocaleString();
    } catch (err) {
      return date;
    }
  };

  const formatAmount = (amount) => {
    return `₹${Number(amount || 0).toLocaleString("en-IN", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    })}`;
  };

  if (loading) {
    return (
      <div className="account-details-page">
        <div className="account-details-container">
          <p>Loading account details...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="account-details-page">
        <div className="account-details-container">
          <div className="error-message">{error}</div>

          <button
            type="button"
            onClick={() => navigate(-1)}
            className="back-button"
          >
            ← Back
          </button>
        </div>
      </div>
    );
  }

  if (!account) {
    return (
      <div className="account-details-page">
        <div className="account-details-container">
          <p>Account not found.</p>

          <button
            type="button"
            onClick={() => navigate(-1)}
            className="back-button"
          >
            ← Back
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="account-details-page">
      <div className="account-details-container">

        {/* Header */}
        <div className="account-details-header">
          <div>
            <h1>Account Details</h1>

            <p>
              View account information and transaction history
            </p>
          </div>

          <button
            type="button"
            onClick={() => navigate(-1)}
            className="back-button"
          >
            ← Back
          </button>
        </div>

        {/* Account Information */}
        <div className="account-card">
          <h2>Account Information</h2>

          <div className="account-info-grid">

            <div className="info-item">
              <span className="info-label">
                Account ID
              </span>

              <span className="info-value">
                {account.accountId || accountId}
              </span>
            </div>

            <div className="info-item">
              <span className="info-label">
                Account Number
              </span>

              <span className="info-value">
                {account.accountNumber || "-"}
              </span>
            </div>

            <div className="info-item">
              <span className="info-label">
                Account Holder
              </span>

              <span className="info-value">
                {account.accountHolderName || "-"}
              </span>
            </div>

            <div className="info-item">
              <span className="info-label">
                Account Type
              </span>

              <span className="info-value">
                {account.accountType || "-"}
              </span>
            </div>

            <div className="info-item">
              <span className="info-label">
                Current Balance
              </span>

              <span className="info-value balance">
                {formatAmount(account.balance)}
              </span>
            </div>

            <div className="info-item">
              <span className="info-label">
                Created Date
              </span>

              <span className="info-value">
                {formatDate(account.createdDate)}
              </span>
            </div>
          </div>
        </div>

        {/* ============================= */}
        {/* TRANSACTION ACTIONS */}
        {/* ============================= */}

        {canTransact && (
          <div className="quick-actions">

            <h2>Account Actions</h2>

            <p className="action-description">
              You can manage transactions for your account.
            </p>

            <div className="action-buttons">

              {/* Deposit */}
              <Link
                to={`/accounts/${accountId}/deposit`}
                className="action-button deposit-button"
              >
                <span className="action-icon">＋</span>

                <span>
                  <strong>Deposit</strong>
                  <small>Add money to your account</small>
                </span>
              </Link>

              {/* Withdraw */}
              <Link
                to={`/accounts/${accountId}/withdraw`}
                className="action-button withdraw-button"
              >
                <span className="action-icon">−</span>

                <span>
                  <strong>Withdraw</strong>
                  <small>Withdraw money from your account</small>
                </span>
              </Link>

              {/* Transfer */}
              <Link
                to={`/accounts/${accountId}/transfer`}
                className="action-button transfer-button"
              >
                <span className="action-icon">⇄</span>

                <span>
                  <strong>Transfer</strong>
                  <small>Transfer money to another account</small>
                </span>
              </Link>

            </div>
          </div>
        )}

        {/* ============================= */}
        {/* ADMIN MESSAGE */}
        {/* ============================= */}

        {isAdmin && (
          <div className="admin-notice">
            <h3>Administrator View</h3>

            <p>
              Administrators can view account details and
              transaction history, but cannot perform
              deposit, withdrawal, or transfer transactions.
            </p>
          </div>
        )}

        {/* ============================= */}
        {/* OTHER USER / ACCESS MESSAGE */}
        {/* ============================= */}

        {!isAdmin && !isOwner && role && (
          <div className="access-notice">
            <h3>Access Restricted</h3>

            <p>
              You can only perform transactions on your own
              account.
            </p>
          </div>
        )}

        {/* ============================= */}
        {/* TRANSACTION HISTORY */}
        {/* ============================= */}

        <div className="transaction-section">

          <div className="transaction-header">
            <div>
              <h2>Transaction History</h2>

              <p>
                Previous transactions for this account
              </p>
            </div>

            {canTransact && (
              <Link
                to={`/accounts/${accountId}/transactions`}
                className="view-all-button"
              >
                View All
              </Link>
            )}
          </div>

          {transactions.length === 0 ? (
            <div className="no-transactions">
              <p>No transactions found.</p>
            </div>
          ) : (
            <div className="transaction-table-container">

              <table className="transaction-table">

                <thead>
                  <tr>
                    <th>Date</th>
                    <th>Type</th>
                    <th>Amount</th>
                    <th>Description</th>
                    <th>Recipient Account</th>
                  </tr>
                </thead>

                <tbody>

                  {transactions.map((transaction) => (
                    <tr key={transaction.transactionId}>

                      <td>
                        {formatDate(
                          transaction.transactionDate
                        )}
                      </td>

                      <td>
                        <span
                          className={`transaction-type ${String(
                            transaction.transactionType || ""
                          ).toLowerCase()}`}
                        >
                          {transaction.transactionType || "-"}
                        </span>
                      </td>

                      <td>
                        {formatAmount(transaction.amount)}
                      </td>

                      <td>
                        {transaction.description || "-"}
                      </td>

                      <td>
                        {transaction.recipientAccountId || "-"}
                      </td>

                    </tr>
                  ))}

                </tbody>

              </table>

            </div>
          )}

        </div>

      </div>
    </div>
  );
};

export default AccountDetails;
